class TestCircuitBreaker:
    """Tests for CircuitBreaker."""

    def _build_instance(self, name="test_cb", failure_threshold=5, recovery_timeout=60.0, half_open_max_calls=1):
        return CircuitBreaker(
            name=name,
            failure_threshold=failure_threshold,
            recovery_timeout=recovery_timeout,
            half_open_max_calls=half_open_max_calls,
        )

    def test_construction(self):
        """CircuitBreaker can be instantiated with mocked dependencies."""
        try:
            instance = self._build_instance()
        except (Exception, SystemExit) as e:
            pytest.skip(f"Requires domain-specific construction setup: {e}")
            return
        assert isinstance(instance, CircuitBreaker)

    def test_construction_with_config(self):
        """CircuitBreaker can be instantiated with a config object."""
        config = CircuitBreakerConfig(failure_threshold=3, timeout_seconds=30.0)
        instance = CircuitBreaker(name="test_cb", config=config)
        assert isinstance(instance, CircuitBreaker)
        assert instance.config.failure_threshold == 3

    def test_state_property(self):
        """Test CircuitBreaker.state property."""
        instance = self._build_instance()
        result = instance.state
        assert isinstance(result, CircuitState)
        assert result == CircuitState.CLOSED

    def test_failure_count_property(self):
        """Test CircuitBreaker.failure_count property."""
        instance = self._build_instance()
        result = instance.failure_count
        assert isinstance(result, int)
        assert result == 0

    def test_success_count_property(self):
        """Test CircuitBreaker.success_count property."""
        instance = self._build_instance()
        result = instance.success_count
        assert isinstance(result, int)
        assert result == 0

    def test_allow_request_closed_state(self):
        """Test allow_request returns True in CLOSED state."""
        instance = self._build_instance()
        result = instance.allow_request()
        assert result is True

    def test_allow_request_open_state(self):
        """Test allow_request returns False in OPEN state."""
        instance = self._build_instance(failure_threshold=1)
        # Force circuit to open by recording a failure
        instance.record_failure()
        result = instance.allow_request()
        assert result is False

    def test_allow_request_half_open_state(self):
        """Test allow_request in HALF_OPEN state."""
        instance = self._build_instance(failure_threshold=1, recovery_timeout=0.1)
        # Force circuit to open
        instance.record_failure()
        # Wait for timeout to transition to HALF_OPEN
        time.sleep(0.15)
        result = instance.allow_request()
        assert result is True

    def test_record_success(self):
        """Test record_success in CLOSED state."""
        instance = self._build_instance()
        instance.record_success()
        assert instance.success_count == 1
        assert instance.failure_count == 0

    def test_record_failure_closed_to_open(self):
        """Test record_failure transitions from CLOSED to OPEN."""
        instance = self._build_instance(failure_threshold=2)
        instance.record_failure()
        assert instance.state == CircuitState.CLOSED
        instance.record_failure()
        assert instance.state == CircuitState.OPEN

    def test_record_failure_half_open_to_open(self):
        """Test record_failure transitions from HALF_OPEN to OPEN."""
        instance = self._build_instance(failure_threshold=1, recovery_timeout=0.1)
        # Open the circuit
        instance.record_failure()
        # Wait for half-open
        time.sleep(0.15)
        instance.allow_request()  # This transitions to HALF_OPEN
        # Record failure in half-open
        instance.record_failure()
        assert instance.state == CircuitState.OPEN

    def test_get_state_info(self):
        """Test get_state_info returns correct data."""
        instance = self._build_instance()
        info = instance.get_state_info()
        assert info["name"] == "test_cb"
        assert info["state"] == "closed"
        assert info["failure_count"] == 0
        assert info["success_count"] == 0

    def test_get_metrics(self):
        """Test get_metrics returns correct data."""
        instance = self._build_instance()
        metrics = instance.get_metrics()
        assert "name" in metrics
        assert "state" in metrics
        assert "failure_count" in metrics

    def test_force_close(self):
        """Test force_close transitions to CLOSED."""
        instance = self._build_instance(failure_threshold=1)
        instance.record_failure()
        assert instance.state == CircuitState.OPEN
        instance.force_close()
        assert instance.state == CircuitState.CLOSED
        assert instance.failure_count == 0

    def test_force_open(self):
        """Test force_open transitions to OPEN."""
        instance = self._build_instance()
        assert instance.state == CircuitState.CLOSED
        instance.force_open()
        assert instance.state == CircuitState.OPEN

    def test_reset(self):
        """Test reset clears all state."""
        instance = self._build_instance(failure_threshold=1)
        instance.record_failure()
        instance.record_success()
        instance.reset()
        assert instance.state == CircuitState.CLOSED
        assert instance.failure_count == 0
        assert instance.success_count == 0

    def test_get_failure_rate(self):
        """Test get_failure_rate calculation."""
        instance = self._build_instance()
        rate = instance.get_failure_rate()
        assert rate == 0.0
        instance.record_failure()
        rate = instance.get_failure_rate()
        assert 0.0 <= rate <= 1.0

    def test_get_state_history(self):
        """Test get_state_history returns state transitions."""
        instance = self._build_instance(failure_threshold=1)
        history = instance.get_state_history()
        assert len(history) == 0
        instance.record_failure()
        history = instance.get_state_history()
        assert len(history) == 1
        assert history[0]["to_state"] == "open"

    def test_validate(self):
        """Test validate method."""
        instance = self._build_instance()
        result = instance.validate()
        assert result["is_valid"] is True
        assert len(result["errors"]) == 0

    def test_to_dict(self):
        """Test to_dict method."""
        instance = self._build_instance()
        data = instance.to_dict()
        assert "name" in data
        assert "state" in data
        assert "version" in data

    def test_from_dict(self):
        """Test from_dict class method."""
        data = {
            "name": "restored_cb",
            "state": "closed",
            "failure_count": 0,
            "success_count": 0,
            "failure_threshold": 3,
            "success_threshold": 2,
            "timeout_seconds": 30.0,
            "half_open_max_calls": 1,
            "record_failure_window_seconds": 120.0,
            "last_failure_time": None,
            "open_time": None,
            "version": 1,
        }
        instance = CircuitBreaker.from_dict(data)
        assert isinstance(instance, CircuitBreaker)
        assert instance.name == "restored_cb"


