def test_with_circuit_breaker_fallback():
    """Test with_circuit_breaker uses fallback on failure."""
    from kernel.circuit_breaker import get_circuit_breaker_registry

    # Reset registry to ensure clean state
    registry = get_circuit_breaker_registry()
    registry._breakers.clear()

    # Use a circuit breaker with failure_threshold=1 so it opens after first failure
    @with_circuit_breaker(name="failing_func3", fallback_value="fallback_result")
    def failing_function():
        raise ValueError("test error")

    # Manually set the threshold to 1 by getting the circuit breaker and modifying it
    from kernel.circuit_breaker import get_circuit_breaker
    cb = get_circuit_breaker("failing_func3")
    cb.config.failure_threshold = 1

    # First call will fail and open circuit (threshold is now 1)
    with pytest.raises(ValueError):
        failing_function()

    # Verify circuit is now open
    assert cb.state.value == "open"

    # Second call should return fallback (circuit is open)
    result = failing_function()
    assert result == "fallback_result"
